import {escape} from './markdown.js';
import {cleanProfile} from './profile.js';
export function editProfile({value,dialog,save}){
 const p=cleanProfile(value);
 const field=(key,label,value,multi=false)=>`<div class="field"><label for="p-${key}">${label}</label>${multi?`<textarea id="p-${key}" rows="5">${escape(value)}</textarea>`:`<input id="p-${key}" value="${escape(value)}">`}</div>`;
 const d=dialog(`<h2>Perfil y secciones</h2><p class="hint">Elige qué quieres compartir. Los cambios se publican para todos al guardar.</p><form id="profile-form"><label><input type="checkbox" id="p-enabled" ${p.enabled?'checked':''}> Mostrar “Sobre mí”</label>${field('name','Nombre',p.name)}${field('headline','Presentación breve',p.headline)}${field('bio','Sobre mí',p.bio,true)}${field('location','Ubicación (opcional)',p.location)}${field('avatar','Foto: enlace HTTPS',p.avatar)}<label><input type="checkbox" id="p-certificatesEnabled" ${p.certificatesEnabled?'checked':''}> Mostrar certificados</label><div id="certificate-rows"></div><button class="btn secondary" type="button" id="add-certificate">+ Certificado</button><label><input type="checkbox" id="p-hobbiesEnabled" ${p.hobbiesEnabled?'checked':''}> Mostrar pasatiempos</label><div id="hobby-rows"></div><button class="btn secondary" type="button" id="add-hobby">+ Pasatiempo</button><h3>Mis enlaces</h3><div id="link-rows"></div><button class="btn secondary" type="button" id="add-link">+ Enlace</button><p class="error" id="profile-error" role="alert"></p><div class="actions"><button class="btn" type="submit">Publicar perfil</button><button class="btn secondary" type="button" data-close>Cerrar</button></div></form>`);
 d.classList.add('preview-dialog');
 function row(container,type,fields,data={}){const el=document.createElement('fieldset');el.className='profile-item';el.dataset.type=type;el.innerHTML=fields.map(([key,label])=>`<label>${label}<input data-key="${key}" value="${escape(data[key]||'')}" ${key==='url'?'type="url" placeholder="https://…"':''}></label>`).join('')+'<button type="button" class="btn secondary">Quitar</button>';el.querySelector('button').onclick=()=>el.remove();d.querySelector(container).append(el);}
 const certificate=c=>row('#certificate-rows','certificate',[['name','Certificado'],['issuer','Institución'],['date','Fecha'],['url','Enlace de verificación (opcional)']],c);
 const hobby=h=>row('#hobby-rows','hobby',[['name','Pasatiempo'],['description','Descripción']],h);
 const link=l=>row('#link-rows','link',[['label','Nombre del enlace'],['url','Dirección HTTPS']],l);
 p.certificates.forEach(certificate);p.hobbies.forEach(hobby);p.links.forEach(link);
 d.querySelector('#add-certificate').onclick=()=>certificate();d.querySelector('#add-hobby').onclick=()=>hobby();d.querySelector('#add-link').onclick=()=>link();
 d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('[type=submit]');b.disabled=true;d.querySelector('#profile-error').textContent='';try{const next={};for(const k of ['name','headline','bio','location','avatar'])next[k]=d.querySelector('#p-'+k).value;for(const k of ['enabled','certificatesEnabled','hobbiesEnabled'])next[k]=d.querySelector('#p-'+k).checked;for(const [key,type] of [['certificates','certificate'],['hobbies','hobby'],['links','link']])next[key]=[...d.querySelectorAll(`[data-type=${type}]`)].map(el=>Object.fromEntries([...el.querySelectorAll('[data-key]')].map(i=>[i.dataset.key,i.value])));for(const url of [next.avatar,...next.certificates.map(c=>c.url),...next.links.map(l=>l.url)])if(url&&!/^https:\/\//i.test(url))throw Error('Usa enlaces que comiencen por https://.');await save(cleanProfile(next));d.close();}catch(e){d.querySelector('#profile-error').textContent=e.message;}finally{b.disabled=false;}};
}
